90→            while (i < input.length) {
                const char = input[i];

                // Track bracket depth
                if (char === '[') bracketDepth++;
                if (char === ']') bracketDepth--;

                if (char === '(' && bracketDepth === 0) {
                    const raw = buffer.trim();
                    const nextCtx = { ...ctx };
100→
                    if (raw.startsWith('&')) {
